const cut = new Date(Date.now()-60*864e5).toISOString().slice(0,10);
const r = items.map(i=>i.json).filter(x=>!x.LastUsed || x.LastUsed < cut).sort((a,b)=>(a.LastUsed||'0').localeCompare(b.LastUsed||'0'))[0];
return r ? [{ json: r }] : [];

